int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    // Bubble sort
    for (int i = 0; i < N; ++i) {
        bool swapped = false;
        for (int j = 0; j + 1 < N - i; ++j) {
            if (a[j] > a[j+1]) {
                swap(a[j], a[j+1]);
                swapped = true;
            }
        }
        if (!swapped) break; // array is already sorted
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << a[i];
    }
    cout << '\n';

return 0;
}

