    int N;
    if (!(cin >> N)) return 0;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    // Selection sort
    for (int i = 0; i < N; ++i) {
        int minIdx = i;
        for (int j = i+1; j < N; ++j) {
            if (a[j] < a[minIdx]) minIdx = j;
        }
        swap(a[i], a[minIdx]);
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << a[i];
    }
    cout << '\n';

return 0;
}

